-- SPOTS production data model (Supabase/PostgreSQL)
create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null,headline text,bio text,avatar_url text,created_at timestamptz default now());
create table if not exists properties(id bigint generated by default as identity primary key,name text not null,district text not null,tier text not null,base_value numeric(14,2) not null check(base_value>=0),asset_wealth numeric(14,2) not null default 0 check(asset_wealth>=0),status text not null default 'available' check(status in('available','owned','listed')),x numeric not null,y numeric not null,height integer not null default 90,color text not null default '#58d7ff',created_at timestamptz default now());
create table if not exists ownership(id uuid primary key default gen_random_uuid(),property_id bigint not null references properties(id),owner_id uuid not null references profiles(id),share_bps integer not null check(share_bps between 1 and 10000),acquired_at timestamptz default now(),unique(property_id,owner_id));
create table if not exists credentials(id uuid primary key default gen_random_uuid(),owner_id uuid not null references profiles(id),kind text not null,title text not null,issuer text,verification_status text not null default 'pending' check(verification_status in('pending','verified','rejected')),public boolean default false,created_at timestamptz default now());
create table if not exists listings(id uuid primary key default gen_random_uuid(),property_id bigint not null references properties(id),seller_id uuid not null references profiles(id),asking_price numeric(14,2) not null check(asking_price>0),status text not null default 'open' check(status in('open','accepted','cancelled','expired')),created_at timestamptz default now());
create table if not exists bids(id uuid primary key default gen_random_uuid(),listing_id uuid not null references listings(id),bidder_id uuid not null references profiles(id),amount numeric(14,2) not null check(amount>0),status text not null default 'pending' check(status in('pending','accepted','rejected','withdrawn')),created_at timestamptz default now());
create table if not exists transfers(id uuid primary key default gen_random_uuid(),property_id bigint not null references properties(id),from_owner uuid references profiles(id),to_owner uuid not null references profiles(id),amount numeric(14,2),created_at timestamptz default now());
alter table profiles enable row level security;alter table properties enable row level security;alter table ownership enable row level security;alter table credentials enable row level security;alter table listings enable row level security;alter table bids enable row level security;alter table transfers enable row level security;
create policy "public profiles" on profiles for select using(true);create policy "own profile update" on profiles for update using(auth.uid()=id);
create policy "public properties" on properties for select using(true);create policy "public ownership" on ownership for select using(true);
create policy "public verified credentials" on credentials for select using(public=true and verification_status='verified');create policy "owner credentials" on credentials for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
create policy "public listings" on listings for select using(true);create policy "seller listings" on listings for insert with check(auth.uid()=seller_id);create policy "seller listing update" on listings for update using(auth.uid()=seller_id);
create policy "bidder reads bids" on bids for select using(auth.uid()=bidder_id);create policy "bidder creates bid" on bids for insert with check(auth.uid()=bidder_id);create policy "bidder withdraws bid" on bids for update using(auth.uid()=bidder_id);
create policy "public transfers" on transfers for select using(true);
-- Ownership transfers/payment confirmation must execute only through privileged server functions, never directly from browser clients.
